@push('scripts')
<script>
(function(){
var perfIndex={{ count($performanceRows) }},adIndex={{ count($advertisingRows) }},activeUpload=null,stores=@json($storeOptions),agencies=@json($agencyOptions),media=@json($mediaOptions);
function esc(v){var d=document.createElement('div');d.textContent=v==null?'':v;return d.innerHTML}
function storeOptions(){return '<option value="">请选择店铺</option>'+stores.map(function(s){return '<option value="'+esc(s.store_name)+'" data-domain="'+esc(s.domain)+'">'+esc(s.store_name)+(s.domain?'（'+esc(s.domain)+'）':'')+'</option>'}).join('')}
function agencyOptions(){return '<option value="">请选择代理</option>'+agencies.map(function(a){return '<option value="'+esc(a.name)+'" data-media="'+esc(a.media)+'">'+esc(a.name)+(a.media?'（'+esc(a.media)+'）':'')+'</option>'}).join('')}
function mediaOptions(){return '<option value="">请选择媒体</option>'+media.map(function(m){return '<option value="'+esc(m)+'">'+esc(m)+'</option>'}).join('')}
function upload(name){return '<label class="fashion-upload"><i class="fa fa-picture-o"></i> 选择/粘贴截图<input type="file" accept="image/jpeg,image/png,image/webp" name="'+name+'"><span class="fashion-upload-name">支持 Ctrl+V</span></label>'}
function performanceRow(i){return '<tr><td><input class="form-control" value="{{ addslashes($user->name) }}" disabled></td><td><select class="form-control field-store js-store" name="performance['+i+'][store_name]" required>'+storeOptions()+'</select></td><td><input class="form-control field-domain js-domain" name="performance['+i+'][domain]" readonly></td><td><input type="number" step="0.01" min="0" class="form-control js-revenue" name="performance['+i+'][revenue_usd]" required></td><td><input type="number" min="0" class="form-control js-orders" name="performance['+i+'][order_count]" required></td><td>'+upload('performance['+i+'][screenshot]')+'</td><td><textarea class="form-control" rows="2" name="performance['+i+'][remark]"></textarea></td><td><button class="btn btn-danger btn-xs" type="button" data-remove-row><i class="fa fa-trash"></i></button></td></tr>'}
function advertisingRow(i){return '<tr><td><select class="form-control js-agency" name="advertising['+i+'][agency]" required>'+agencyOptions()+'</select></td><td><select class="form-control js-media" name="advertising['+i+'][media]" required>'+mediaOptions()+'</select></td><td><input class="form-control field-account" name="advertising['+i+'][account_name]" required></td><td><input class="form-control field-number" name="advertising['+i+'][account_number]" required></td><td><input type="number" step="0.01" min="0" class="form-control js-book-spend" name="advertising['+i+'][book_spend_usd]" required></td><td><input type="number" step="0.01" min="0" class="form-control js-actual-spend" name="advertising['+i+'][actual_spend_usd]" required></td><td>'+upload('advertising['+i+'][screenshot]')+'</td><td><textarea class="form-control" rows="2" name="advertising['+i+'][remark]"></textarea></td><td><button class="btn btn-danger btn-xs" type="button" data-remove-row><i class="fa fa-trash"></i></button></td></tr>'}
function totals(){var revenue=0,orders=0,spend=0;document.querySelectorAll('.js-revenue').forEach(function(x){revenue+=parseFloat(x.value)||0});document.querySelectorAll('.js-orders').forEach(function(x){orders+=parseInt(x.value)||0});document.querySelectorAll('.js-actual-spend').forEach(function(x){spend+=parseFloat(x.value)||0});document.getElementById('total-revenue').textContent='$'+revenue.toFixed(2);document.getElementById('total-orders').textContent=orders;document.getElementById('total-spend').textContent='$'+spend.toFixed(2);document.getElementById('total-roi').textContent=(spend>0?revenue/spend:0).toFixed(2)}
document.addEventListener('click',function(e){var add=e.target.closest('[data-add-row]');if(add){var type=add.dataset.addRow,target=document.getElementById(type+'-rows');target.insertAdjacentHTML('beforeend',type==='performance'?performanceRow(perfIndex++):advertisingRow(adIndex++));return}var remove=e.target.closest('[data-remove-row]');if(remove){var body=remove.closest('tbody');if(body.children.length>1)remove.closest('tr').remove();totals();return}var zone=e.target.closest('.fashion-upload');if(zone)activeUpload=zone});
document.addEventListener('change',function(e){if(e.target.matches('.fashion-upload input[type=file]')){var zone=e.target.closest('.fashion-upload'),file=e.target.files[0];if(file){zone.classList.add('has-file');zone.querySelector('.fashion-upload-name').textContent=file.name}}if(e.target.matches('.js-store')){var option=e.target.options[e.target.selectedIndex],domain=e.target.closest('tr').querySelector('.js-domain');domain.value=option?option.getAttribute('data-domain')||'':''}if(e.target.matches('.js-agency')){var option=e.target.options[e.target.selectedIndex],select=e.target.closest('tr').querySelector('.js-media'),value=option?option.getAttribute('data-media')||'':'';if(value)select.value=value}totals()});
document.addEventListener('input',function(e){if(e.target.matches('.js-revenue,.js-orders,.js-actual-spend'))totals()});
document.addEventListener('paste',function(e){var items=e.clipboardData&&e.clipboardData.items;if(!items)return;var image=null;for(var i=0;i<items.length;i++){if(items[i].type.indexOf('image/')===0){image=items[i].getAsFile();break}}if(!image)return;var zone=activeUpload||document.querySelector('.fashion-upload:hover');if(!zone)return;var input=zone.querySelector('input[type=file]'),transfer=new DataTransfer();transfer.items.add(new File([image],'clipboard-'+Date.now()+'.png',{type:image.type||'image/png'}));input.files=transfer.files;zone.classList.add('has-file');zone.querySelector('.fashion-upload-name').textContent=input.files[0].name;e.preventDefault()});
totals();
})();
</script>
@endpush
